package uk.co.traynor.privategallery.core.arcade;
import java.util.Arrays;
/** Directions: right, down, left, up. A bounded queue prevents rapid-input reversal. */
public final class SnakeGame {
 public static final int WIDTH=16,SIZE=256;
 private final int[] body,queue;public final int direction,food,score;public final long seed;public final boolean paused,over;
 public SnakeGame(int[] body,int direction,int[] queue,int food,int score,long seed,boolean paused,boolean over){ArcadeCodec.require(body.length>=3&&body.length<=SIZE&&direction>=0&&direction<4&&queue.length<=2&&score==body.length-3);boolean[] seen=new boolean[SIZE];for(int i=0;i<body.length;i++){int cell=body[i];ArcadeCodec.require(cell>=0&&cell<SIZE&&!seen[cell]);seen[cell]=true;if(i>0)ArcadeCodec.require(Math.abs(cell%WIDTH-body[i-1]%WIDTH)+Math.abs(cell/WIDTH-body[i-1]/WIDTH)==1);}if(!over){int dx=body[0]%WIDTH-body[1]%WIDTH,dy=body[0]/WIDTH-body[1]/WIDTH;int heading=dx==1?0:dy==1?1:dx==-1?2:3;ArcadeCodec.require(direction==heading);}int d=direction;for(int q:queue){ArcadeCodec.require(q>=0&&q<4&&q!=d&&q!=(d+2)%4);d=q;}ArcadeCodec.require((body.length==SIZE&&food==-1&&over)||(body.length<SIZE&&food>=0&&food<SIZE&&!seen[food]));this.body=body.clone();this.queue=queue.clone();this.direction=direction;this.food=food;this.score=score;this.seed=seed;this.paused=paused;this.over=over;}
 public static SnakeGame create(long seed){int[] body={136,135,134};ArcadeCodec.Random r=new ArcadeCodec.Random(seed);return new SnakeGame(body,0,new int[0],spawn(body,r),0,r.seed,true,false);}
 public int[] body(){return body.clone();}public int[] queue(){return queue.clone();}
 public SnakeGame pause(boolean value){return new SnakeGame(body,direction,value?new int[0]:queue,food,score,seed,value,over);}
 public SnakeGame turn(int d){ArcadeCodec.require(d>=0&&d<4);if(paused||over||queue.length>=2)return this;int last=queue.length==0?direction:queue[queue.length-1];if(d==last||d==(last+2)%4)return this;int[] next=Arrays.copyOf(queue,queue.length+1);next[next.length-1]=d;return new SnakeGame(body,direction,next,food,score,seed,paused,over);}
 public SnakeGame tick(){if(paused||over)return this;int d=queue.length==0?direction:queue[0];int[] q=queue.length==0?queue:Arrays.copyOfRange(queue,1,queue.length);int x=body[0]%WIDTH+(d==0?1:d==2?-1:0),y=body[0]/WIDTH+(d==1?1:d==3?-1:0);int head=y*WIDTH+x;boolean eats=head==food;boolean collision=x<0||x>=WIDTH||y<0||y>=WIDTH;for(int i=0;i<body.length-(eats?0:1);i++)if(body[i]==head)collision=true;if(collision)return new SnakeGame(body,d,new int[0],food,score,seed,true,true);int[] next=new int[body.length+(eats?1:0)];next[0]=head;System.arraycopy(body,0,next,1,next.length-1);ArcadeCodec.Random r=new ArcadeCodec.Random(seed);int f=eats?spawn(next,r):food;return new SnakeGame(next,d,q,f,score+(eats?1:0),r.seed,false,next.length==SIZE);}
 private static int spawn(int[] body,ArcadeCodec.Random r){if(body.length==SIZE)return -1;boolean[] occupied=new boolean[SIZE];for(int cell:body)occupied[cell]=true;int at=r.next(SIZE-body.length);for(int i=0;i<SIZE;i++)if(!occupied[i]&&at--==0)return i;throw new AssertionError();}
 public String encode(){return ArcadeCodec.encode(3,out->{ArcadeCodec.ints(out,body);out.writeInt(direction);ArcadeCodec.ints(out,queue);out.writeInt(food);out.writeInt(score);out.writeLong(seed);out.writeBoolean(paused);out.writeBoolean(over);});}
 public static SnakeGame decode(String raw){return ArcadeCodec.decode(raw,3,in->new SnakeGame(ArcadeCodec.ints(in,3,SIZE),in.readInt(),ArcadeCodec.ints(in,0,2),in.readInt(),in.readInt(),in.readLong(),ArcadeCodec.bool(in),ArcadeCodec.bool(in)));}
}
